import io
import os

import pytest
from conftest import TEST_BACKUP_ID, TEST_DISPLAY_KEY, TEST_KEY, TEST_LOCAL_KEY, encrypt_file

from signal_sqlite import BackupError
from signal_sqlite import constants as c
from signal_sqlite.crypto import (
    attachment_keys,
    decrypt_authenticated_file,
    derive_backup_key,
    derive_message_keys,
    normalize_key,
    read_key_file,
)

# Signal's published account-keys/message-backup vectors, not generated by this project.
EXPECTED_BACKUP_KEY = "ea26a2ddb5dba5ef9e34e1b8dea1f5ae7f255306a6d2d883e542306eaa9fe985"
EXPECTED_HMAC_KEY = "f425e22a607c529717e1e1b29f9fe139f9d1c7e7d01e371c7753c544a3026649"
EXPECTED_AES_KEY = "e143f4ad5668d8bfed2f88562f0693f53bda2c0e55c9d71730f30e24695fd6df"
KEY_GROUP_WIDTH = 4
KEY_SEPARATOR = " \r\n\t"
PUBLIC_FILE_MODE = 0o644
SYMLINK_NAME = "linked.key"
ENCRYPTED_FILE_NAME = "encrypted"
TAMPER_INDEX = c.AES_IV_LENGTH
TEST_BYTE_XOR_MASK = 1
GET_UID_ATTRIBUTE = "getuid"
INVALID_UNICODE_KEY = "K" + TEST_KEY[1:]


def test_official_signal_key_vectors():
    backup_key = derive_backup_key(TEST_KEY)
    keys = derive_message_keys(backup_key, TEST_BACKUP_ID)
    assert backup_key.hex() == EXPECTED_BACKUP_KEY
    assert keys.hmac_key.hex() == EXPECTED_HMAC_KEY
    assert keys.aes_key.hex() == EXPECTED_AES_KEY


def test_whitespace_and_bom_key_file(backup):
    grouped = KEY_SEPARATOR.join(
        TEST_DISPLAY_KEY[index : index + KEY_GROUP_WIDTH]
        for index in range(0, len(TEST_DISPLAY_KEY), KEY_GROUP_WIDTH)
    )
    backup.key_path.write_text(grouped, encoding=c.KEY_TEXT_ENCODING)
    assert read_key_file(backup.key_path) == TEST_KEY


@pytest.mark.parametrize("value", [TEST_KEY.upper(), TEST_DISPLAY_KEY, TEST_DISPLAY_KEY.lower()])
def test_signal_display_keys_match_official_vector(value):
    assert normalize_key(value) == TEST_KEY
    assert derive_backup_key(value).hex() == EXPECTED_BACKUP_KEY


@pytest.mark.parametrize("value", ["", "short", INVALID_UNICODE_KEY, TEST_KEY + "!", TEST_KEY[:-1]])
def test_invalid_keys_are_not_echoed(value):
    with pytest.raises(BackupError) as error:
        normalize_key(value)
    assert TEST_KEY not in str(error.value)


def test_key_file_requires_private_permissions(backup):
    backup.key_path.chmod(PUBLIC_FILE_MODE)
    with pytest.raises(BackupError, match="mode 0600"):
        read_key_file(backup.key_path)


def test_key_file_rejects_symlink(backup):
    link = backup.key_path.with_name(SYMLINK_NAME)
    link.symlink_to(backup.key_path)
    with pytest.raises(OSError):
        read_key_file(link)


def test_key_file_rejects_foreign_owner(backup, monkeypatch):
    other_uid = os.getuid() + 1
    monkeypatch.setattr(os, GET_UID_ATTRIBUTE, lambda: other_uid)
    with pytest.raises(BackupError, match="owned by you"):
        read_key_file(backup.key_path)


def test_authentication_happens_before_plaintext_is_written(tmp_path):
    keys = attachment_keys(TEST_LOCAL_KEY)
    encrypted = bytearray(encrypt_file(b"Sensitive synthetic text", keys.aes_key, keys.hmac_key))
    encrypted[TAMPER_INDEX] ^= TEST_BYTE_XOR_MASK
    path = tmp_path / ENCRYPTED_FILE_NAME
    path.write_bytes(encrypted)
    sink = io.BytesIO()
    with pytest.raises(BackupError, match="Authentication failed"):
        decrypt_authenticated_file(path, sink, keys)
    assert sink.getvalue() == b""
